using System.Diagnostics;using System.Globalization;using WindowsGSH.Core.Modules;using WindowsGSH.Core.Query;using WindowsGSH.Core.Servers;namespace WindowsGSH.Modules.Factorio;public sealed class FactorioModule:IGameServerModule,IManifestBackedModule,IModuleExistingServerImportCapability,IModulePortCapability{private ModuleManifest? _m;private string _d=AppContext.BaseDirectory;private ModuleManifest M=>_m??=ModuleManifest.Load(Path.Combine(_d,"module.json"));public string Id=>M.Id;public string Name=>M.Name;public string Version=>M.Version;public ModuleCapabilities Capabilities=>M.ToCapabilities(false,false);public SteamInstallDefinition? SteamInstall=>null;public ModuleRuntimeDefinition Runtime=>M.ToRuntime();public void Configure(ModuleManifest m,string d){_m=m;_d=d;}public IReadOnlyList<ConfigFieldDefinition>GetConfigFields()=>M.ToConfigFields();public IReadOnlyList<ServerPortDefinition>GetPorts()=>M.ToPorts();public IReadOnlyList<ServerAddonDefinition>GetAddonDefinitions()=>M.ToAddons();public IReadOnlyList<ServerBackupTargetDefinition>GetBackupTargets()=>M.ToBackupTargets();public string GetServerName(IReadOnlyDictionary<string,object?>s)=>"Factorio Server";public ServerDisplayInfo GetDisplayInfo(ServerInstance i)=>new("0.0.0.0",Get(i,"network.port","34197"),"");public Task<IReadOnlyDictionary<string,object?>>ReadConfigFileSettingsAsync(ServerInstance i,CancellationToken c)=>FactorioSettings.ReadAsync(i.InstallPath,c);public Task WriteConfigFileSettingsAsync(ServerInstance i,CancellationToken c)=>FactorioSettings.WriteAsync(i,c);public Task<InstallPlan>CreateInstallPlanAsync(ServerInstance i,CancellationToken c)=>Task.FromResult(new InstallPlan("manual","",i.InstallPath,["Install or copy the authenticated official Windows Factorio package into this folder."]));public Task<ProcessStartInfo>CreateStartInfoAsync(ServerInstance i,CancellationToken c){c.ThrowIfCancellationRequested();var p=new ProcessStartInfo{FileName=Path.Combine(i.InstallPath,Runtime.StartPath),WorkingDirectory=i.InstallPath,UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};p.ArgumentList.Add("--start-server");p.ArgumentList.Add(Path.Combine(i.InstallPath,"saves",SafeFile(Get(i,"server.saveName","world.zip"))));var settings=Path.Combine(i.InstallPath,"data","server-settings.json");if(File.Exists(settings)){p.ArgumentList.Add("--server-settings");p.ArgumentList.Add(settings);}return Task.FromResult(p);}public async Task<Process?>StartAsync(ServerInstance i,CancellationToken c){if(!IsInstallValid(i))throw new FileNotFoundException("bin/x64/factorio.exe was not found.");var p=new Process{StartInfo=await CreateStartInfoAsync(i,c),EnableRaisingEvents=true};p.Start();return p;}public async Task StopAsync(ServerInstance i,CancellationToken c){foreach(var p in ServerProcessLocator.FindProcesses(this,i.InstallPath))using(p){if(p.HasExited)continue;p.CloseMainWindow();await Task.Delay(5000,c);if(!p.HasExited){p.Kill(true);await p.WaitForExitAsync(c);}}}public bool IsInstallValid(ServerInstance i)=>File.Exists(Path.Combine(i.InstallPath,Runtime.StartPath));public string?GetConsoleLogPath(ServerInstance i)=>i.InstallPath;public Task<QueryResult>QueryAsync(ServerInstance i,CancellationToken c)=>Task.FromResult(new QueryResult(ModuleServerStatus.Unknown,Message:"WindowsGSH uses process status for Factorio."));public Task<string>ExecuteRconCommandAsync(ServerInstance i,string x,CancellationToken c)=>throw new NotSupportedException();public Task<IReadOnlyList<Process>>StartAddonProcessesAsync(ServerInstance i,CancellationToken c)=>Task.FromResult<IReadOnlyList<Process>>([]);public ServerAddonStatus GetAddonStatus(ServerInstance i,string x)=>new(x,false,false,"Unknown addon");public Task InstallAddonAsync(ServerInstance i,string x,CancellationToken c)=>throw new NotSupportedException();public Task RemoveAddonAsync(ServerInstance i,string x,CancellationToken c)=>throw new NotSupportedException();public bool CanImport(string p){try{return File.Exists(Path.Combine(Resolve(p),Runtime.StartPath));}catch{return false;}}public Task<ModuleExistingServerImportProbe>PreviewImportAsync(string p,CancellationToken c){var s=Path.GetFullPath(p);var i=Resolve(s);if(!File.Exists(Path.Combine(i,Runtime.StartPath)))throw new InvalidDataException("bin/x64/factorio.exe was not found.");return PreviewAsync(s,i,c);}private async Task<ModuleExistingServerImportProbe>PreviewAsync(string sourcePath,string installPath,CancellationToken cancellationToken){var values=await FactorioSettings.ReadAsync(installPath,cancellationToken);var name=values.TryGetValue("server.name",out var configuredName)&&configuredName is not null?configuredName.ToString()!:Path.GetFileName(sourcePath);return new ModuleExistingServerImportProbe(name,installPath,values,["Installation remains managed by the game vendor."]);}private string Resolve(string p){var s=Path.GetFullPath(p);if(File.Exists(Path.Combine(s,Runtime.StartPath)))return s;var f=Path.Combine(s,"serverfiles");return File.Exists(Path.Combine(f,Runtime.StartPath))?f:s;}private static int Num(ServerInstance i,string k,int f)=>int.TryParse(Get(i,k,f.ToString(CultureInfo.InvariantCulture)),out var v)&&v>=1&&v<=65535?v:f;private static string SafeFile(string v){var n=Path.GetFileName(v);if(n!=v||string.IsNullOrWhiteSpace(n))throw new InvalidDataException("Save file name is invalid.");return n;}private static string Memory(string v){v=v.Trim();if(v.Length<2||!char.IsDigit(v[0])||v.Any(c=>!char.IsDigit(c)&&c is not 'G' and not 'g' and not 'M' and not 'm'))throw new InvalidDataException("Memory value is invalid.");return v;}private static string Get(ServerInstance i,string k,string f)=>i.Settings.TryGetValue(k,out var v)&&v is not null?v.ToString()!.Trim():f;}
